// test/fixtures/apmedia/creatorYaml.js
// A Plex Media YAML shaped like the one the Archipelago Launcher's Options Creator (AP 0.6.8) exports:
// name, description and game, then the game's mapping with every option the Creator gave a widget,
// in widget order (the order of apworld/tests/fixtures/options_creator_default.yaml, which
// Archipelago's own code wrote; test/apMediaYaml.test.js holds the two to the same keys). Values are
// as the Creator stores them and Utils.dump writes them: a Range as an int, a Choice by its option
// name, a Toggle as a bool, a NamedRange's special name lowercased (and quoted where YAML 1.1 would
// read it as a bool), random from an option's Random toggle, '' for an empty FreeText. The Creator
// writes no requires, no entries and no list_info.
//
// Each value is raw YAML text, so a test can hand in any spelling; undefined leaves the key out.

const OPTIONS = Object.freeze({
	progression_balancing: '50',
	accessibility: 'full',
	list_preset: 'mixed',
	list_movies: 'preset',
	list_shows: '2',
	list_albums: 'preset',
	list_books: 'preset',
	list_titles: '\'Alien; Aliens\'',
	list_playlist: '\'\'',
	list_collection: '\'\'',
	list_genre: '\'\'',
	list_years: '\'\'',
	list_unwatched: 'true',
	list_max_episodes: '24',
	list_label: '\'\'',
	starting_unlocks: '3',
	goal_percent: 'random',
	tv_unlock: 'episodes',
	episodes_per_unlock: '3',
	locked_watches: 'bank',
	wild_tickets: '2',
	checkpoint_items: 'filler_only',
	timesanity_strict: 'false',
	timesanity_movies: '15',
	timesanity_episodes: '10',
	timesanity_albums: '\'off\'',
	timesanity_books: '30',
	snack_variety: 'true',
	fast_forwards: '2',
	remote_controls: '1',
	snack_bar_trades: '3',
	snack_bar_price: '10',
	trap_percentage: '0',
	buffering_weight: '2',
	rights_expired_weight: '2',
	commercial_break_weight: '1',
	shuffle_mode_weight: '1',
	rewind_weight: '1',
	intermission_weight: '1',
	slow_motion_weight: '1',
	local_items: '[]',
	non_local_items: '[]',
	start_inventory: '{}',
	start_hints: '[]',
	start_location_hints: '[]',
	exclude_locations: '[]',
	priority_locations: '[]',
});

/**
 * @param {object} [over] option key to raw YAML text, or undefined to leave the key out
 * @param {{name?: string, top?: string[]}} [opts] the name as raw YAML text; extra top-level lines
 * @returns {string}
 */
function creatorYaml(over = {}, { name = 'Zack', top = [] } = {}) {
	const lines = [`name: ${name}`, 'description: YAML generated by Archipelago 0.6.8.', 'game: Plex Media', ...top, 'Plex Media:'];
	for (const [key, value] of Object.entries({ ...OPTIONS, ...over })) {
		if (value !== undefined) lines.push(`  ${key}: ${value}`);
	}
	return `${lines.join('\n')}\n`;
}

module.exports = { creatorYaml, CREATOR_OPTIONS: OPTIONS };
